isComplete() {
  return (
    !!this.incoming.hostname &&
    !!this.incoming.port &&
    this.incoming.socketType != -1 &&
    !!this.incoming.auth &&
    !!this.incoming.username &&
    (!!this.outgoing.existingServerKey ||
      this.outgoing.useGlobalPreferredServer ||
      (!!this.outgoing.hostname &&
        !!this.outgoing.port &&
        this.outgoing.socketType != -1 &&
        !!this.outgoing.auth &&
        !!this.outgoing.username))
  );
},

validateSocketType() {
  this.incoming.socketType = lazy.InputSanitizer.enum(
    this.incoming.socketType,
    [0, 1, 2, 3],
    0
  );

  this.outgoing.socketType = lazy.InputSanitizer.enum(
    this.outgoing.socketType,
    [0, 1, 2, 3],
    0
  );
},

isIncomingEditedComplete() {
  return (
    (this.isExchangeConfig() &&
      this.incoming.exchangeURL &&
      this.incoming.username &&
      this.incoming.auth) ||
    (!this.isExchangeConfig() &&
      !!this.incoming.hostname &&
      !!this.incoming.port &&
      !!this.incoming.username)
  );
},
